mapper.select:
SELECT EXISTS (
    SELECT 1 FROM agent_attachments a
    JOIN workspace_members wm ON wm.workspace_id = a.workspace_id
        AND wm.user_id = #{userId} AND wm.status = 'ACTIVE'
    WHERE a.id = #{id} AND a.workspace_id = #{workspaceId} AND a.project_id = #{projectId}
        AND a.uploaded_by = #{userId}
)
